    'RegistrationText'=>'A regisztrált SimpleRisk példányok azonnal hozzáférést kapnak az Upgrade and Secure Controls Framework (SCF) extrákhoz. Az Upgrade Extra lehetővé teszi a SimpleRisk példány biztonsági mentését és frissítését egyetlen gombnyomással. A Secure Controls Framework (SCF) Extra közös vezérlési keretrendszert biztosít, amely integrálva van a SimpleRisk Governance funkcióba. A SimpleRisk regisztrálásakor az Ön regisztrációs adatai a SimpleRisk által üzemeltetett szerverre kerülnek. A SimpleRisk a megadott regisztrációs információkat arra használja fel, hogy értesítse ügyfeleit az új kiadásokról és biztonsági frissítésekről. A SimpleRisk regisztrációja felveszi Önt marketingkommunikációinkra, de bármikor leiratkozhat a jelen közleményekben található leiratkozási hivatkozás segítségével. A SimpleRisk tiszteletben tartja ügyfeleink magánéletét, és a SimpleRisk regisztrációs folyamata során rendelkezésünkre bocsátott információkat soha nem adjuk el harmadik félnek.',
