    // Configure Hub - tile descriptions (system category)
    'SettingsDesc'                        => 'Rendszerszintű beállítások konfigurálása: alap URL, biztonság, alapértelmezett nyelv, időzóna, kockázatértékelési alapértelmezések és egyebek.',
    'SettingsPreferencesDesc'             => 'Alapértelmezett értékek és viselkedési beállítások a SimpleRiskben: nyelv, időzóna, auditállapotok, kockázattérképezési követelmények, felhasználói felület viselkedésének kapcsolói és hasonlók.',
    'SettingsFileUploadDesc'              => 'Engedélyezett fájlfeltöltési típusok és méretkorlátok a különböző fájlmelléklet-mezőkre vonatkozóan.',
    'SettingsMailDesc'                    => 'SMTP-konfiguráció a kimenő e-mail értesítésekhez, beleértve az átvitelt, a hosztot, a hitelesítést és a válaszcímet.',
