    'UpgradeStatementsApplied' => 'Elindítva {started} · {count} utasítás alkalmazva',
    // The Upgrade Extra's pre-upgrade check of the instance it is sitting on
    'UpgradeCheckingInstance' => 'Ennek a példánynak az ellenőrzése',
